/**
 * SourceListResponse
 *
 * EP-01。全件を返す。最上位の `unavailable` は常に `{}`(行に属さない項目がない)。
 */
export type SourceListResponse = {
    /**
     * Items
     */
    items: Array<SourceListItem>;
    unavailable: Unavailable;
};

/**
 * SourceSettings
 *
 * 登録・更新が返すデータソースの設定(EP-03・04。B 2.11)。
 *
 * Crawler が返した保存内容を確かめてから作る(読めなければ 502 で、この型にならない)ので、
 * `null` を許すのは `ttl_days`(日で割り切れないとき)と `schedule_cron`(手動のみ)だけ。
 */
export type SourceSettings = {
    /**
     * Connector Config
     */
    connector_config: {
        [key: string]: unknown;
    };
    /**
     * Connector Type
     */
    connector_type: string;
    /**
     * Min Delete Count
     */
    min_delete_count: number;
    /**
     * Ratio Threshold Percent
     */
    ratio_threshold_percent: number | number;
    /**
     * Schedule Cron
     */
    schedule_cron: string | null;
    /**
     * Source Id
     */
    source_id: string;
    status: SourceStatus;
    /**
     * Ttl Days
     */
    ttl_days: number | null;
    /**
     * Ttl Seconds
     */
    ttl_seconds: number;
    /**
     * Updated At
     */
    updated_at: string;
};

/**
 * SourceStatus
 *
 * データソース設定の `status`(B 2.11)。
 */
export type SourceStatus = 'active' | 'deleting';

/**
 * StartCrawlBody
 *
 * EP-06 の本文。本文なし・`{}` は、どちらも既定の `false`(B 4.1)。
 */
export type StartCrawlBody = {
    /**
     * Force Delete
     */
    force_delete?: boolean;
    /**
     * Rewrite Mode
     */
    rewrite_mode?: boolean;
};

/**
 * SummaryPendingDocument
 */
export type SummaryPendingDocument = {
    /**
     * Document Id
     */
    document_id: string;
    /**
     * External Id
     */
    external_id: string | null;
    /**
     * Indexed At
     */
    indexed_at: string | null;
    /**
     * Mime Type
     */
    mime_type: string | null;
    /**
     * Source Updated At
     */
    source_updated_at: string | null;
    /**
     * Title
     */
    title: string | null;
    unavailable: Unavailable;
};

/**
 * TabCounts
 *
 * 各タブの総件数。取得できなかったタブは `null`(最上位の `unavailable.tab_counts.<タブ>`)。
 */
export type TabCounts = {
    /**
     * Extract Failed
     */
    extract_failed: number | null;
    /**
     * Oversize
     */
    oversize: number | null;
    /**
     * Skipped
     */
    skipped: number | null;
    /**
     * Summary Pending
     */
    summary_pending: number | null;
};

export type Unavailable = {
    [key: string]: UnavailableReason;
};

/**
 * UnavailableReason
 *
 * `unavailable` の値(取得できなかった項目の理由。B 2.2)。
 */
export type UnavailableReason = 'store_unavailable' | 'search_index_unavailable' | 'timeout' | 'malformed';

/**
 * UpdateSourceBody
 *
 * EP-04 の本文。EP-03 の本文から `source_id`・`connector_type` を除いたもの(全置換)。
 *
 * ここで検証するのは形(型・必須・未知の項目)だけ。`ttl_days` と `ttl_seconds` の排他・必須と、
 * 値の範囲・桁は、換算と一緒に `services` が検証する(B 2.4。範囲の違反は、形の違反がないときに
 * すべて返す)。`connector_config` の中身と `schedule_cron` の書式は検証しない(Crawler に任せる)。
 */
export type UpdateSourceBody = {
    /**
     * Connector Config
     */
    connector_config: {
        [key: string]: unknown;
    };
    /**
     * Min Delete Count
     */
    min_delete_count: number;
    /**
     * Ratio Threshold Percent
     */
    ratio_threshold_percent: number;
    /**
     * Schedule Cron
     */
    schedule_cron?: string | null;
    /**
     * Ttl Days
     */
    ttl_days?: number;
    /**
     * Ttl Seconds
     */
    ttl_seconds?: number;
};

